#include "stock_native_detached_turret_runtime.hpp"

#include <algorithm>
#include <cmath>
#include <stdexcept>

namespace stock_native_detached_turret {
namespace {
Point add(const Point&a,const Point&b){return {{a[0]+b[0],a[1]+b[1],a[2]+b[2]}};}
Point sub(const Point&a,const Point&b){return {{a[0]-b[0],a[1]-b[1],a[2]-b[2]}};}
Point scale(const Point&a,double k){return {{a[0]*k,a[1]*k,a[2]*k}};}
double dot(const Point&a,const Point&b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}
Point cross(const Point&a,const Point&b){return {{a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]}};}
double length(const Point&p){return std::sqrt(dot(p,p));}
Point unit(const Point&p){const auto size=length(p);return size>epsilon?scale(p,1./size):Point{};}
Point mul(const Matrix&m,const Point&v){return {{m[0]*v[0]+m[1]*v[1]+m[2]*v[2],m[3]*v[0]+m[4]*v[1]+m[5]*v[2],m[6]*v[0]+m[7]*v[1]+m[8]*v[2]}};}
Matrix transpose(const Matrix&m){return {{m[0],m[3],m[6],m[1],m[4],m[7],m[2],m[5],m[8]}};}
Matrix matrix(const Point&a){
    const auto sy=std::sin(a[0]),cy=std::cos(a[0]),sp=std::sin(a[1]),cp=std::cos(a[1]),sr=std::sin(a[2]),cr=std::cos(a[2]);
    // Preserve the source's three successive vector transforms, rather than
    // replacing their intermediate floating-point operations with a product.
    Matrix out{};for(unsigned j=0;j<3;++j){Point p{};p[j]=1.;Point r{{cr*p[0]-sr*p[1],sr*p[0]+cr*p[1],p[2]}};Point t{{r[0],cp*r[1]-sp*r[2],sp*r[1]+cp*r[2]}};Point v{{cy*t[0]+sy*t[2],t[1],-sy*t[0]+cy*t[2]}};for(unsigned i=0;i<3;++i)out[3*i+j]=v[i];}return out;
}
Matrix inverse(const Matrix&m){const auto a=m[0],b=m[1],c=m[2],d=m[3],e=m[4],f=m[5],g=m[6],h=m[7],i=m[8];Matrix cof{{e*i-f*h,c*h-b*i,b*f-c*e,f*g-d*i,a*i-c*g,c*d-a*f,d*h-e*g,b*g-a*h,a*e-b*d}};const auto det=a*cof[0]+b*cof[3]+c*cof[6];if(std::abs(det)<epsilon)throw std::invalid_argument("Detached component inertia is singular");for(auto&v:cof)v/=det;return cof;}
Matrix rotate(const Matrix&m,const Point&omega,double dt){const auto speed=length(omega);if(speed*dt<=1.e-12)return m;const auto axis=scale(omega,1./speed);const auto cosine=std::cos(speed*dt),sine=std::sin(speed*dt);Matrix out{};for(unsigned j=0;j<3;++j){Point v{{m[j],m[3+j],m[6+j]}};v=add(add(scale(v,cosine),scale(cross(axis,v),sine)),scale(axis,dot(axis,v)*(1.-cosine)));for(unsigned i=0;i<3;++i)out[3*i+j]=v[i];}return out;}
Point angles(const Matrix&m){const auto pitch=std::asin(std::clamp(-m[5],-1.,1.));if(std::abs(std::cos(pitch))>1.e-8)return {{std::atan2(m[2],m[8]),pitch,std::atan2(m[3],m[4])}};return {{std::atan2(-m[6],m[0]),pitch,0.}};}
double skin(const std::vector<Point>&points){double out=0.;for(const auto&p:points)for(auto v:p)out=std::max(out,std::abs(v));return std::max(epsilon,out*std::ldexp(1.,-21));}
double energy(const Point&v){return .5*(v[0]*v[0]+v[1]*v[1]+v[2]*v[2]);}
bool same(const Impact&a,const Impact&b){return a.point==b.point&&a.normal==b.normal&&a.velocity==b.velocity&&a.energy==b.energy;}
bool same(const Frame&a,const Frame&b){if(a.position!=b.position||a.attitude!=b.attitude||a.centre!=b.centre||a.velocity!=b.velocity||a.angular_velocity!=b.angular_velocity||a.grounded!=b.grounded||a.sleeping!=b.sleeping||a.impact_serial!=b.impact_serial||bool(a.impact)!=bool(b.impact)||a.acknowledgements.size()!=b.acknowledgements.size())return false;if(a.impact&&!same(*a.impact,*b.impact))return false;for(unsigned i=0;i<a.acknowledgements.size();++i){const auto&x=a.acknowledgements[i];const auto&y=b.acknowledgements[i];if(!(x.player==y.player)||x.sequence!=y.sequence||x.linear!=y.linear||x.angular!=y.angular)return false;}return true;}
bool same(const std::vector<Box>&a,const std::vector<Box>&b){if(a.size()!=b.size())return false;for(unsigned i=0;i<a.size();++i)if(a[i].center!=b[i].center||a[i].axes!=b[i].axes)return false;return true;}
std::vector<std::size_t> nearby(const Body&body,double dt,const std::vector<Vehicle>&vehicles){const auto end=add(body.com,add(scale(body.velocity,dt),{{0.,-.5*9.81*dt*dt,0.}}));Point low{},high{};for(unsigned i=0;i<3;++i){low[i]=std::min(body.com[i],end[i])-body.radius;high[i]=std::max(body.com[i],end[i])+body.radius;}const auto apex=body.velocity[1]/9.81;if(apex>0.&&apex<dt)high[1]=body.com[1]+.5*body.velocity[1]*apex+body.radius;std::vector<std::size_t> out;for(unsigned n=0;n<vehicles.size();++n){if(vehicles[n].boxes.empty())continue;Point vl{{INFINITY,INFINITY,INFINITY}},vh{{-INFINITY,-INFINITY,-INFINITY}};for(const auto&box:vehicles[n].boxes)for(unsigned i=0;i<3;++i){double extent=0.;for(const auto&axis:box.axes)extent+=std::abs(axis[i]);vl[i]=std::min(vl[i],box.center[i]-extent);vh[i]=std::max(vh[i],box.center[i]+extent);}bool overlaps=true;for(unsigned i=0;i<3;++i)overlaps=overlaps&&low[i]<=vh[i]&&high[i]>=vl[i];if(overlaps)out.push_back(n);}return out;}
}
Properties properties(const std::vector<Component>&components){
    Properties out;std::vector<Point> centres,sizes;for(const auto&part:components){if(!std::isfinite(part.mass)||part.mass<=0.)throw std::invalid_argument("Detached component weight must be positive");Point centre{};for(unsigned i=0;i<3;++i){const auto lo=part.geometry.bounds.minimum[i],hi=part.geometry.bounds.maximum[i];if(!std::isfinite(lo)||!std::isfinite(hi)||lo>=hi||!std::isfinite(part.geometry.offset[i]))throw std::invalid_argument("Detached component bounds are invalid");centre[i]=(lo+hi)*.5+part.geometry.offset[i];}centres.push_back(centre);sizes.push_back(sub(part.geometry.bounds.maximum,part.geometry.bounds.minimum));out.mass+=part.mass;}
    if(components.empty())throw std::invalid_argument("Detached components are empty");
    for(unsigned i=0;i<3;++i){double sum=0.;for(unsigned n=0;n<components.size();++n)sum+=components[n].mass*centres[n][i];out.centre[i]=sum/out.mass;}
    for(unsigned n=0;n<components.size();++n){const auto r=sub(centres[n],out.centre);for(unsigned i=0;i<3;++i)for(unsigned j=0;j<3;++j){double diagonal=0.;if(i==j){double sum=0.;for(unsigned k=0;k<3;++k)if(k!=i)sum+=sizes[n][k]*sizes[n][k];diagonal=sum/12.+dot(r,r);}out.inertia[3*i+j]+=components[n].mass*diagonal-components[n].mass*r[i]*r[j];}}
    out.inverse_inertia=inverse(out.inertia);return out;
}
Body::Body(std::vector<Component> components,const Frame&frame):components_(std::move(components)){
    properties=stock_native_detached_turret::properties(components_);rotation=matrix(frame.attitude);com=add(frame.position,mul(rotation,properties.centre));velocity=frame.velocity;angular=frame.angular_velocity;grounded=frame.grounded;sleeping=frame.sleeping;impact_serial=frame.impact_serial;impact=frame.impact;acknowledgements=frame.acknowledgements;
    for(const auto&c:components_)for(const auto x:{c.geometry.bounds.minimum[0],c.geometry.bounds.maximum[0]})for(const auto y:{c.geometry.bounds.minimum[1],c.geometry.bounds.maximum[1]})for(const auto z:{c.geometry.bounds.minimum[2],c.geometry.bounds.maximum[2]}){const auto p=add({{x,y,z}},c.geometry.offset);local_points_.push_back(p);radius=std::max(radius,length(sub(p,properties.centre)));}
}
Point Body::position()const{return sub(com,mul(rotation,properties.centre));}
Frame Body::frame()const{Frame out;out.position=position();out.attitude=angles(rotation);out.centre=properties.centre;out.velocity=velocity;out.angular_velocity=angular;out.grounded=grounded;out.sleeping=sleeping;out.impact_serial=impact_serial;out.impact=impact;out.acknowledgements=acknowledgements;return out;}
std::vector<Box> Body::boxes()const{std::vector<Box> out;for(const auto&c:components_){Box box;Point centre{};for(unsigned i=0;i<3;++i)centre[i]=(c.geometry.bounds.minimum[i]+c.geometry.bounds.maximum[i])*.5+c.geometry.offset[i];box.center=add(position(),mul(rotation,centre));for(unsigned i=0;i<3;++i){Point axis{};axis[i]=(c.geometry.bounds.maximum[i]-c.geometry.bounds.minimum[i])*.5;box.axes.push_back(mul(rotation,axis));}out.push_back(std::move(box));}return out;}
std::vector<Point> Body::points()const{std::vector<Point> out;const auto origin=position();for(const auto&p:local_points_)out.push_back(add(origin,mul(rotation,p)));return out;}
Point Body::inverseInertia(const Point&p)const{Matrix world{};for(unsigned j=0;j<3;++j){Point axis{};axis[j]=1.;const auto column=mul(rotation,mul(properties.inverse_inertia,mul(transpose(rotation),axis)));for(unsigned i=0;i<3;++i)world[3*i+j]=column[i];}return mul(world,p);}
Point Body::pointVelocity(const Point&p)const{return add(velocity,cross(angular,sub(p,com)));}
double Body::denominator(const Point&p,const Point&normal)const{const auto arm=cross(sub(p,com),normal);return 1./properties.mass+dot(arm,inverseInertia(arm));}
void Body::momentum(const Point&linear,const Point&angular_momentum){velocity=add(velocity,scale(linear,1./properties.mass));angular=add(angular,inverseInertia(angular_momentum));if(length(linear)+length(angular_momentum)>epsilon)sleeping=false;}
void Body::impulse(const Point&value,const Point&p){momentum(value,cross(sub(p,com),value));}
double Body::kineticEnergy()const{const auto local=mul(transpose(rotation),angular);return .5*properties.mass*dot(velocity,velocity)+.5*dot(local,mul(properties.inertia,local));}
void Body::integrate(double dt){com=add(com,add(scale(velocity,dt),{{0.,-.5*9.81*dt*dt,0.}}));velocity=add(velocity,{{0.,-9.81*dt,0.}});rotation=rotate(rotation,angular,dt);}
std::optional<BoxContact> boxContact(const Box&a,const Box&b,bool horizontal){
    for(unsigned i=0;i<3;++i){double extent=0.;for(const auto&v:a.axes)extent+=std::abs(v[i]);for(const auto&v:b.axes)extent+=std::abs(v[i]);if(std::abs(a.center[i]-b.center[i])>extent+epsilon)return {};}
    std::vector<Point> candidates=a.axes;candidates.insert(candidates.end(),b.axes.begin(),b.axes.end());for(const auto&x:a.axes)for(const auto&y:b.axes)candidates.push_back(cross(x,y));if(horizontal){if(!boxContact(a,b))return {};for(auto&v:candidates)v[1]=0.;}
    const auto delta=sub(a.center,b.center);std::optional<BoxContact> best;for(auto axis:candidates){if(length(axis)<=epsilon)continue;axis=unit(axis);double gap=0.;for(const auto&v:a.axes)gap+=std::abs(dot(v,axis));for(const auto&v:b.axes)gap+=std::abs(dot(v,axis));gap-=std::abs(dot(delta,axis));if(gap < -epsilon)return {};if(!best||gap<best->depth)best=BoxContact{dot(delta,axis)>=0.?axis:scale(axis,-1.),std::max(0.,gap),{}};}
    if(!best)return {};const auto middle=scale(add(a.center,b.center),.5);const auto face=[&](const Box&box,const Point&direction){auto point=box.center;for(const auto&half:box.axes){const auto size=length(half);if(size<=epsilon)continue;const auto u=scale(half,1./size);const auto projection=dot(u,direction);const auto distance=std::abs(projection)>epsilon?std::copysign(size,projection):std::clamp(dot(sub(middle,box.center),u),-size,size);point=add(point,scale(u,distance));}return point;};best->point=scale(add(face(a,scale(best->normal,-1.)),face(b,best->normal)),.5);return best;
}
std::vector<Box> vehicleSupportBoxes(const VehicleGeometry&geometry,const VehiclePose&pose,bool attached){
    std::vector<Box> out;out.push_back(stock_native_bot_turret::worldBox(geometry.chassis,pose.position,pose.attitude));const auto position=pose.separate_hull?pose.hull_position:pose.position;const auto attitude=pose.separate_hull?pose.hull_attitude:pose.attitude;out.push_back(stock_native_bot_turret::worldBox(geometry.hull,position,attitude));
    if(attached){const auto parent=matrix(attitude),turret=matrix({{pose.aim_yaw-pose.attitude[0],0.,0.}});for(unsigned i=0;i<2;++i){auto component=i?geometry.gun:geometry.turret;component.offset={};auto box=stock_native_bot_turret::worldBox(component,{},i?Point{{0.,pose.gun_pitch,0.}}:Point{});box.center=add(position,mul(parent,add(geometry.turret_mount,mul(turret,add(box.center,i?geometry.gun_mount:Point{})))));for(auto&axis:box.axes)axis=mul(parent,mul(turret,axis));out.push_back(std::move(box));}}return out;
}
std::optional<Contact> vehicleContact(const Body&body,const std::vector<Box>&input,double mass,const Point&velocity,bool horizontal){
    if(!(mass>0.)||!std::isfinite(mass))throw std::invalid_argument("Vehicle collision mass is unavailable");std::vector<Box> boxes;for(const auto&b:input){double reach=body.radius;for(const auto&v:b.axes)reach+=length(v);if(length(sub(body.com,b.center))<=reach)boxes.push_back(b);}if(boxes.empty())return {};
    double bottom=INFINITY,vehicle_bottom=INFINITY;for(const auto&p:body.points())bottom=std::min(bottom,p[1]);for(const auto&b:boxes){double extent=0.;for(const auto&v:b.axes)extent+=std::abs(v[1]);vehicle_bottom=std::min(vehicle_bottom,b.center[1]-extent);}const bool side=body.grounded&&bottom<vehicle_bottom;std::vector<BoxContact> contacts,sides;for(const auto&a:body.boxes())for(const auto&b:boxes){double extent=0.;for(const auto&v:b.axes)extent+=std::abs(v[1]);const bool component_side=side||(body.grounded&&a.center[1]<b.center[1]+extent-epsilon);auto hit=boxContact(a,b,component_side);if(hit){contacts.push_back(*hit);if(component_side&&hit->depth>epsilon)sides.push_back(*hit);}}if(!sides.empty())contacts=std::move(sides);if(horizontal&&!side)contacts.erase(std::remove_if(contacts.begin(),contacts.end(),[](const BoxContact&c){return !(std::abs(c.normal[1])<std::max(std::abs(c.normal[0]),std::abs(c.normal[2])));}),contacts.end());if(contacts.empty())return {};
    const auto best=*std::min_element(contacts.begin(),contacts.end(),[](const BoxContact&a,const BoxContact&b){return a.depth<b.depth;});auto normal=best.normal;if(horizontal){normal=unit({{normal[0],0.,normal[2]}});if(length(normal)<=epsilon)return {};}const auto inv_vehicle=1./mass;const auto relative=dot(sub(body.pointVelocity(best.point),velocity),normal);Point impulse{};if(relative<0.)impulse=scale(normal,-relative/(body.denominator(best.point,normal)+inv_vehicle));const auto correction=scale(normal,best.depth/(1./body.properties.mass+inv_vehicle));Contact out;out.normal=normal;out.point=best.point;out.momentum=impulse;out.angular_momentum=cross(sub(best.point,body.com),impulse);out.delta=scale(impulse,-inv_vehicle);out.body_correction=scale(correction,1./body.properties.mass);out.vehicle_correction=scale(correction,-inv_vehicle);return out;
}
void sceneryStep(Body&body,double dt,World&world){
    const auto before=body.points();body.integrate(dt);const auto after=body.points();auto combined=before;combined.insert(combined.end(),after.begin(),after.end());const auto tolerance=skin(combined);std::vector<BoxContact> contacts;
    for(unsigned i=0;i<before.size();++i){const auto direction=unit(sub(after[i],before[i]));const auto hit=world.collide(add(sub(before[i],scale(direction,tolerance)),{{0.,tolerance,0.}}),sub(add(after[i],scale(direction,tolerance)),{{0.,tolerance,0.}}));if(!hit)continue;const auto normal=unit(hit->normal);if(length(normal)<=epsilon)continue;const auto penetration=std::max(0.,tolerance-dot(sub(after[i],hit->point),normal));if(dot(sub(after[i],before[i]),normal)>tolerance)continue;contacts.push_back({normal,penetration,hit->point});}
    const auto was_grounded=body.grounded;body.grounded=std::any_of(contacts.begin(),contacts.end(),[](const BoxContact&c){return c.normal[1]>0.;});if(contacts.empty()){body.support_points.clear();return;}const auto initial_velocity=body.velocity;Point correction{};for(unsigned pass=0;pass<8;++pass){bool changed=false;for(const auto&hit:contacts){const auto remaining=hit.depth-dot(correction,hit.normal);if(remaining>epsilon){correction=add(correction,scale(hit.normal,remaining));changed=true;}}if(!changed)break;}body.com=add(body.com,correction);
    for(unsigned pass=0;pass<8;++pass)for(const auto&hit:contacts){const auto closing=dot(body.pointVelocity(hit.point),hit.normal);if(closing<0.)body.impulse(scale(hit.normal,-closing/body.denominator(hit.point,hit.normal)),hit.point);const auto tangent=sub(body.pointVelocity(hit.point),scale(hit.normal,dot(body.pointVelocity(hit.point),hit.normal)));if(length(tangent)>epsilon){const auto direction=unit(tangent);body.impulse(scale(direction,-length(tangent)/body.denominator(hit.point,direction)),hit.point);}}
    if(!was_grounded&&body.grounded){const auto hit=*std::max_element(contacts.begin(),contacts.end(),[](const BoxContact&a,const BoxContact&b){return a.normal[1]<b.normal[1];});++body.impact_serial;body.impact=Impact{hit.point,hit.normal,initial_velocity,energy(initial_velocity)};}body.support_points.clear();for(const auto&hit:contacts)if(hit.normal[1]>0.&&std::find(body.support_points.begin(),body.support_points.end(),hit.point)==body.support_points.end())body.support_points.push_back(hit.point);
}
bool supportedCom(const Body&body){using P=std::pair<double,double>;std::set<P> unique;for(const auto&p:body.support_points)unique.emplace(p[0],p[2]);if(unique.size()<3)return false;std::vector<P> points(unique.begin(),unique.end()),lower,upper;const auto turn=[](const P&a,const P&b,const P&c){return (b.first-a.first)*(c.second-a.second)-(b.second-a.second)*(c.first-a.first);};for(const auto&p:points){while(lower.size()>=2&&turn(lower[lower.size()-2],lower.back(),p)<=epsilon)lower.pop_back();lower.push_back(p);}for(auto i=points.rbegin();i!=points.rend();++i){while(upper.size()>=2&&turn(upper[upper.size()-2],upper.back(),*i)<=epsilon)upper.pop_back();upper.push_back(*i);}lower.pop_back();upper.pop_back();lower.insert(lower.end(),upper.begin(),upper.end());if(lower.size()<3)return false;const P com{body.com[0],body.com[2]};for(unsigned i=0;i<lower.size();++i)if(turn(lower[i],lower[(i+1)%lower.size()],com)<-epsilon)return false;return true;}
Point translate(Body&body,const Point&displacement,World&world){double fraction=1.;auto points=body.points(),combined=points;for(const auto&p:points)combined.push_back(add(p,displacement));const auto tolerance=skin(combined);const auto direction=unit(displacement);for(const auto&p:points){const auto hit=world.collide(add(sub(p,scale(direction,tolerance)),{{0.,tolerance,0.}}),sub(add(add(p,displacement),scale(direction,tolerance)),{{0.,tolerance,0.}}));if(!hit)continue;const auto normal=unit(hit->normal);const auto closing=-dot(displacement,normal);if(closing<=epsilon)continue;const auto clearance=dot(sub(p,hit->point),normal)-tolerance;fraction=std::min(fraction,std::max(0.,clearance/closing));}const auto actual=scale(displacement,fraction);body.com=add(body.com,actual);return actual;}
double advance(Body&body,double dt,std::vector<Vehicle>&all_vehicles,World&world,std::optional<double> budget){
    double remaining=std::max(0.,dt);std::optional<double> deadline;if(budget)deadline=world.clock()+*budget;auto vehicles=nearby(body,remaining,all_vehicles);if(body.sleeping){const auto tolerance=skin(body.points());bool stable=body.support_points.size()>=3;if(stable)for(const auto&p:body.support_points)if(!world.collide(add(p,{{0.,tolerance,0.}}),sub(p,{{0.,tolerance,0.}}))){stable=false;break;}bool touched=false;for(auto i:vehicles){const auto&v=all_vehicles[i];if(vehicleContact(body,v.boxes,v.mass,v.velocity)){touched=true;break;}}if(stable&&!touched)return remaining;body.sleeping=false;}
    while(remaining>1.e-9){if(remaining<dt&&deadline&&world.clock()>=*deadline)break;const auto step=std::min(step_seconds,remaining);vehicles=nearby(body,step,all_vehicles);const auto had_support=body.grounded;sceneryStep(body,step,world);for(unsigned pass=0;pass<8;++pass){bool touched=false;for(auto i:vehicles){auto&v=all_vehicles[i];const auto hit=vehicleContact(body,v.boxes,v.mass,v.velocity);if(!hit)continue;if(hit->normal[1]>std::max(std::abs(hit->normal[0]),std::abs(hit->normal[2]))){if(!had_support&&!body.grounded){++body.impact_serial;body.impact=Impact{hit->point,hit->normal,body.velocity,energy(body.velocity)};}body.grounded=true;}const bool human_horizontal=v.human&&v.alive&&std::abs(hit->normal[1])<std::max(std::abs(hit->normal[0]),std::abs(hit->normal[2]));if(!human_horizontal){body.momentum(hit->momentum,hit->angular_momentum);touched=touched||length(hit->momentum)>epsilon;if(!v.human&&(length(hit->delta)>epsilon||length(hit->vehicle_correction)>epsilon)){const auto old_boxes=v.boxes;const auto old_velocity=v.velocity;world.applyVehicle(v,*hit,step);touched=touched||!same(v.boxes,old_boxes)||v.velocity!=old_velocity;}}if(length(hit->body_correction)>epsilon){const auto actual=translate(body,hit->body_correction,world);touched=touched||length(actual)>epsilon;}}if(!touched)break;vehicles=nearby(body,0.,all_vehicles);}remaining-=step;}
    if(body.grounded&&supportedCom(body)&&body.kineticEnergy()<.5*body.properties.mass*std::pow(9.81*step_seconds,2)){body.velocity={};body.angular={};body.sleeping=true;}return remaining<=1.e-9?dt:dt-remaining;
}
Frame initialFrame(const Row&row){if(row.flight.body)return *row.flight.body;Frame out;const auto&flight=row.flight;if(flight.duration<=0.){out.position=flight.rest;if(flight.rest_attitude)out.attitude=*flight.rest_attitude;else{constexpr double pi=3.14159265358979323846;out.attitude={{row.attitude[0]+row.spin[0]*flight.duration,std::round((row.attitude[1]+row.spin[1]*flight.duration)/pi)*pi,std::round((row.attitude[2]+row.spin[2]*flight.duration)/pi)*pi}};}return out;}if(flight.segments.empty())throw std::invalid_argument("Detached flight segments are empty");const Segment*segment=&flight.segments.front();for(const auto&candidate:flight.segments)if(candidate.start<=0.)segment=&candidate;const auto elapsed=-segment->start;out.position=add(segment->origin,add(scale(segment->velocity,elapsed),{{0.,-.5*9.81*elapsed*elapsed,0.}}));out.attitude=row.attitude;out.velocity=add(segment->velocity,{{0.,-9.81*elapsed,0.}});out.angular_velocity={{row.spin[1],row.spin[0],row.spin[2]}};return out;}
Row revision(const Row&row,const Body&body,double now_ms){auto out=row;const auto frame=body.frame();out.flight={};out.flight.origin=out.flight.rest=frame.position;out.flight.velocity=frame.velocity;out.flight.segments.push_back({frame.position,frame.velocity,0.,0.});out.flight.contact=frame.impact?std::optional<Point>(frame.impact->point):(body.grounded?std::optional<Point>(frame.position):std::nullopt);out.flight.impact_velocity=frame.impact?frame.impact->velocity:Point{};out.flight.energy=frame.impact?frame.impact->energy:0.;out.flight.landed=bool(frame.impact)||body.grounded;out.flight.rest_attitude=frame.attitude;out.flight.body=frame;out.attitude=frame.attitude;out.spin={};out.support.reset();++out.motion_sequence;out.motion_time_ms=out.created_time_ms=std::int64_t(now_ms);return out;}
bool Runtime::accept(const Row&row,std::vector<Component> components){auto found=entries_.find(row.owner);if(found!=entries_.end()&&row.motion_sequence<=found->second.accepted.motion_sequence)return false;if(found==entries_.end()&&entries_.size()>=12)return false;if(found==entries_.end()){Entry entry;entry.accepted=entry.proposal=row;entry.components=std::move(components);entry.simulation_ms=double(row.created_time_ms);entries_.emplace(row.owner,std::move(entry));order.push_back(row.owner);}else{auto&entry=found->second;entry.accepted=row;if(entry.proposal.motion_sequence<=row.motion_sequence)entry.proposal=row;entry.components=std::move(components);}return true;}
std::vector<Row> Runtime::update(double server_ms,std::vector<Vehicle>&vehicles,const std::vector<PlayerImpulse>&impulses,World&world){std::vector<Row> updates;failures.clear();if(server_ms<0.||server_ms<next_ms_)return updates;if(std::none_of(entries_.begin(),entries_.end(),[](const auto&entry){return bool(entry.second.accepted.flight.body);}))return updates;next_ms_=server_ms+1000.*flight_step_seconds;if(entries_.empty())return updates;for(const auto owner:order){auto found=entries_.find(owner);if(found==entries_.end())continue;auto&entry=found->second;if(!entry.available)continue;const auto saved_entry=entry;const auto output_size=updates.size();const auto saved_vehicles=vehicles;try{world.begin(owner);if(!entry.body)entry.body.emplace(entry.components,initialFrame(entry.proposal));auto&body=*entry.body;for(const auto&input:impulses){if(!(input.turret==owner))continue;const auto&current=input.checkpoint;auto old=std::find_if(body.acknowledgements.begin(),body.acknowledgements.end(),[&](const Checkpoint&c){return c.player==current.player;});if(old!=body.acknowledgements.end()&&current.sequence<=old->sequence)continue;body.momentum(sub(current.linear,old==body.acknowledgements.end()?Point{}:old->linear),sub(current.angular,old==body.acknowledgements.end()?Point{}:old->angular));if(old==body.acknowledgements.end())body.acknowledgements.push_back(current);else *old=current;}const auto previous_ms=entry.simulated?entry.simulation_ms:double(entry.proposal.created_time_ms);const auto elapsed=std::max(0.,(server_ms-previous_ms)/1000.);const auto consumed=advance(body,elapsed,vehicles,world,.004/entries_.size());const auto motion_ms=body.sleeping?server_ms:std::min(server_ms,previous_ms+1000.*consumed);if(motion_ms<server_ms)next_ms_=server_ms;const auto frame=body.frame();if(!entry.published||!same(frame,*entry.published)){auto update=revision(entry.proposal,body,motion_ms);entry.proposal=update;entry.published=frame;updates.push_back(std::move(update));}entry.simulation_ms=motion_ms;entry.simulated=true;world.commit(owner);}catch(const std::exception&error){entry=saved_entry;if(entry.body){const auto frame=entry.body->frame();const auto support=entry.body->support_points;const auto components=entry.body->components();entry.body.emplace(components,frame);entry.body->support_points=support;}vehicles=saved_vehicles;updates.resize(output_size);try{world.rollback(owner);}catch(const std::exception&rollback_error){failures.push_back({owner,rollback_error.what()});}failures.push_back({owner,error.what()});}}return updates;}
const Body* Runtime::body(Owner owner)const{const auto i=entries_.find(owner);return i==entries_.end()||!i->second.body?nullptr:&*i->second.body;}
double Runtime::simulationTime(Owner owner)const{const auto i=entries_.find(owner);return i==entries_.end()?0.:i->second.simulation_ms;}
stock_native_bot_turret::Record obstacleRecord(const Row&r){stock_native_bot_turret::Record out;out.owner=r.owner;out.support=r.support;out.motion_sequence=r.motion_sequence;out.created_time_ms=double(r.created_time_ms);out.duration=r.flight.duration;out.landed=r.flight.landed;out.has_body=bool(r.flight.body);out.rest=r.flight.rest;out.attitude=r.attitude;out.spin=r.spin;out.rest_attitude=r.flight.rest_attitude;return out;}
}
